"""Explicitly authored pending-only native amendments. No semantic inference."""
import copy,json,sys
from pathlib import Path
R=Path(__file__).resolve().parent.parent
sys.path[:0]=[str(R),str(R/'authored')]
import direct_review as d
from review_03250_04250_wire import S
DATA=d.source();PACK=json.loads((R/'worker-notes/review_03250_04250_pending_reread_packet.json').read_text());OLD={x['ordinal']:x for x in PACK['rows']};OUT=[];NOTES=[]
def rel(subject,kind,obj):return dict(subject=subject,type=kind,object=obj)
def view(rid,en,ko,specs,relations=(),terms=()):
 return dict(rid=rid,text=dict(en=en,ko=ko,embedding_text=en+' | '+ko,concept_units=[en],relations=list(relations)),specs=specs,terms=list(terms))
def amendments(n,meaning,views,reason,*,mode='one',boundary=None):
 old=OLD[n]['registered_row'];cid=old['candidate_id'];record=d.corrected_record(DATA['candidates'][cid],old['corrections']);rowspec=[];rids=[v['rid'] for v in views]
 for v in views:
  facts=[]
  for raw in v['specs'].split(';'):
   tag,owner,*prop=raw.split(':');dim,default=S[tag];facts.append((tag,dict(pointer='/content/realization_content/'+v['rid']+'/en',quote=v['text']['en'],dimension=dim,target=owner,property=prop[0] if prop else default,realization_id=v['rid'])))
  rowspec.append((v,facts))
 def effects(facts):
  props=[]
  for _,f in facts:
   p={k:f[k] for k in ('dimension','target','property')}
   if p not in props:props.append(p)
  return dict(dimensions=sorted({p['dimension'] for p in props}),properties=props)
 if mode=='optional':
  assert views[0]['rid']=='base';base=effects(rowspec[0][1]);others=rowspec[1:]
 else:base=dict(dimensions=[],properties=[]);others=rowspec
 base['realizations']=dict(mode=mode,branches=[dict(id=v['rid'],conditions={},context_terms=v['terms'],concept_units=v['text']['concept_units'],effects=effects(f)) for v,f in others])
 corr=copy.deepcopy(old['corrections'])
 corr += [dict(pointer='/effects',before=record['effects'],after=base,reason=reason),dict(pointer='/content/realization_content',before=record['content'].get('realization_content'),after={v['rid']:v['text'] for v in views},reason=reason)]
 row={k:copy.deepcopy(old[k]) for k in ('candidate_id','recommended_kind','rejected_boundaries')};row.update(meaning_summary=meaning,corrections=corr,roles=[],facts=[],uncertainties=[],status='approved',all_roles_considered=True)
 if boundary:row['rejected_boundaries'].append(boundary)
 tags={}
 for v,fs in rowspec:
  for tag,f in fs:
   row['facts'].append(f)
   if tag not in tags:tags[tag]=dict(slot_id=tag,semantic_role=DATA['slot_catalog'][tag]['semantic_role'],scope='positive_alternative',realization_ids=[],rationale=meaning,evidence=[])
   role=tags[tag]
   if v['rid'] not in role['realization_ids']:role['realization_ids'].append(v['rid'])
   role['evidence'].append(copy.deepcopy(f))
 for role in tags.values():
  if set(role['realization_ids'])==set(rids):role['scope']='whole_record'
 row['roles']=list(tags.values());OUT.append(row);NOTES.append(dict(ordinal=n,candidate_id=cid,resolution='approved_with_native_realizations',reason=reason,realization_ids=rids));return row
def retained(n,why):
 old=OLD[n]['registered_row'];row={k:copy.deepcopy(old[k]) for k in ('candidate_id','meaning_summary','recommended_kind','corrections','roles','facts','rejected_boundaries','uncertainties','status','all_roles_considered')};row['uncertainties']=[dict(kind='source_meaning_requires_authorial_refinement',detail=why)];OUT.append(row);NOTES.append(dict(ordinal=n,candidate_id=row['candidate_id'],resolution='pending_retained',reason=why))
